SELECT FROM custom_order_quotes q WHERE q.order_id IN
#{orderId}
AND q.version = (SELECT MAX(v.version) FROM custom_order_quotes v WHERE v.order_id = q.order_id)

mapper.update:
UPDATE custom_order_quotes
   SET status = #{nextStatus},
       accepted_at = #{acceptedAt}
 WHERE id = #{quoteId}
   AND status = #{currentStatus}

UPDATE custom_order_payment_links
   SET status = #{nextStatus},
       used_at = CASE WHEN #{nextStatus} = 'USED' THEN #{at} ELSE used_at END,
       revoked_at = CASE WHEN #{nextStatus} = 'REVOKED' THEN #{at} ELSE revoked_at END
 WHERE id = #{linkId}
   AND status = #{currentStatus}

UPDATE custom_order_payment_links l
  JOIN custom_order_quotes q ON q.id = l.quote_id
   SET l.status = 'REVOKED',
       l.revoked_at = #{at}
 WHERE q.order_id = #{orderId}
   AND l.status = 'ISSUED'

