WHERE EXISTS (SELECT 1 FROM order_items oi
               WHERE oi.order_id = o.id AND oi.product_type = 'CUSTOM')

    AND o.status = #{status}

mapper.update:
UPDATE orders
   SET final_amount = #{finalAmount}
 WHERE id = #{orderId}

UPDATE orders
   SET original_amount = #{originalAmount},
       discount_amount = #{discountAmount},
       final_amount = #{finalAmount}
 WHERE id = #{orderId}

UPDATE orders
   SET pickup_at = #{pickupAt}
 WHERE id = #{orderId}

UPDATE orders
   SET status = 'REJECTED',
       reject_reason = #{reason},
       rejected_at = NOW(6)
 WHERE id = #{orderId}
   AND status = #{currentStatus}
